CREATE TABLE Projects(ProjectId nvarchar(80) PRIMARY KEY,Code nvarchar(40) NOT NULL UNIQUE,Name nvarchar(200) NOT NULL,Client nvarchar(200) NOT NULL,Status nvarchar(30) NOT NULL,BudgetHours decimal(18,2) NOT NULL,HourlyRate decimal(18,2) NOT NULL,StartDate date NULL,EndDate date NULL,Description nvarchar(max) NULL);CREATE TABLE Employees(EmployeeId nvarchar(80) PRIMARY KEY,Name nvarchar(200) NOT NULL,Email nvarchar(320),Active bit NOT NULL);CREATE TABLE TimeEntries(EntryId nvarchar(80) PRIMARY KEY,ProjectId nvarchar(80) REFERENCES Projects(ProjectId),EmployeeId nvarchar(80) REFERENCES Employees(EmployeeId),WorkDate date,StartTime time,EndTime time,Hours decimal(18,2),Activity nvarchar(200),Description nvarchar(max),Billable bit,Invoiced bit,InvoiceDate date,InvoiceReference nvarchar(100));GO
CREATE VIEW vwPowerBIProjectHours AS SELECT t.*,p.Code ProjectCode,p.Name ProjectName,p.Client,p.HourlyRate,t.Hours*p.HourlyRate Amount,e.Name EmployeeName,e.Email EmployeeEmail FROM TimeEntries t JOIN Projects p ON p.ProjectId=t.ProjectId JOIN Employees e ON e.EmployeeId=t.EmployeeId;GO
